const b = $json.body || $json;
const d = new Date(b.ts);
const hora = d.toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit', timeZone: 'Europe/Madrid' });
const nota = (b.nota || '').trim().replace(/\s+/g, ' ');
// {{1}} de la plantilla: el pie de foto y la hora (nunca vacío, Meta lo exige)
const variable = nota ? `${nota} (${hora})` : `(${hora})`;
return [{ json: { url: b.url, variable, phone_number_id: $json.phone_number_id, to: $json.to, template: $json.template, lang: $json.lang } }];
